/**
 * 💡 THOUGHT PROCESS:
 * Drives the Analysis tab — the preview half of the stocks domain only. Unlike the old
 * `StockAnalysisViewModel` (which also held chip-selection state and rendered detail inline in
 * the same screen), detail is now its own pushed screen with its own `StockDetailViewModel`
 * (SavedStateHandle-driven by symbol), so this ViewModel carries no selection state at all — the
 * future Route navigates on tap via a plain lambda, the same way every other pushed destination in
 * this app works (`NewsRoute.onNavigateToWebView`, etc.). "Which symbol is selected" simply isn't
 * this screen's state anymore.
 *
 * Previews ARE sync-flag-driven (`stocks_updated`), so this follows the standard
 * repository+SyncManager / combine+stateIn / onStart+onStop shape every other tab ViewModel uses
 * (`IndicatorsViewModel`, `DashboardViewModel`). `onStart()` also self-triggers a `force = false`
 * fetch as a first-paint pre-warm — `DashboardViewModel` does the same; `SyncManager`'s snapshot
 * listener handles ongoing freshness after that.
 */
@HiltViewModel
class StockAnalysisViewModel @Inject constructor(
    private val repository: StockAnalysisRepository,
    private val syncManager: SyncManager,
    private val intradayRepository: IntradayRepository
) : ViewModel() {

    private val _isLoading = MutableStateFlow(false)
    private val _isRefreshing = MutableStateFlow(false)
    private val _error = MutableStateFlow<UiError?>(null)
    private var intradayTrackingJob: Job? = null
    private var trackedSymbols: Set<String> = emptySet()

    val uiState: StateFlow<StockAnalysisUiState> = combine(
        repository.getStockPreviewsStream(),
        _isLoading,
        _isRefreshing,
        _error
    ) { previews, loading, refreshing, error ->
        StockAnalysisUiState(
            previews = previews,
            isLoading = loading && previews.isEmpty(),
            isRefreshing = refreshing,
            analyzedAsOf = previews.newestAnalyzedAsOf(),
            error = error
        )
    }.stateIn(
        scope = viewModelScope,
        started = SharingStarted.WhileSubscribed(5000),
        initialValue = StockAnalysisUiState(isLoading = true)
    )

    /** Called by the UI when the screen becomes visible. */
    fun onStart() {
        syncManager.startListening()
        fetchPreviews(force = false)

        // Tracks the intraday sparkline for every visible preview, re-diffing whenever the
        // preview list itself changes (a new sync-driven refresh). Every tracked stock is
        // eligible -- the backend polls `resolveActiveSymbols()` unconditionally (spec Part B1),
        // unlike the dashboard's gated ~23-symbol set.
        intradayTrackingJob = viewModelScope.launch {
            repository.getStockPreviewsStream()
                .map { previews -> previews.map { it.symbol } }
                .distinctUntilChanged()
                .collect { symbols ->
                    val newSymbols = symbols.toSet()
                    (trackedSymbols - newSymbols).forEach { intradayRepository.untrackSymbol(it) }
                    (newSymbols - trackedSymbols).forEach { intradayRepository.trackSymbol(it) }
                    trackedSymbols = newSymbols
                }
        }
    }

    /** Called by the UI when the app goes to the background. */
    fun onStop() {
        syncManager.stopListening()
        intradayTrackingJob?.cancel()
        trackedSymbols.forEach { intradayRepository.untrackSymbol(it) }
        trackedSymbols = emptySet()
    }

    /** Thin pass-through so `StockPreviewCard` can collect its own symbol's polled intraday bars. */
    fun getIntradayStream(symbol: String): Flow<IntradaySeries?> =
        intradayRepository.getIntradayStream(symbol)

    /** Called by pull-to-refresh. */
    fun refresh() {
        fetchPreviews(force = true)
    }

    /** Clears any active error (e.g. after a Snackbar is dismissed). */
    fun clearError() {
        _error.value = null
    }

    private fun fetchPreviews(force: Boolean) {
        viewModelScope.launch {
            if (force) _isRefreshing.value = true else _isLoading.value = true
            _error.value = null

            val result = repository.refreshPreviews(force)

            if (result.isFailure) {
                _error.value = result.exceptionOrNull().toUiError()
            }

            _isLoading.value = false
            _isRefreshing.value = false
        }
    }
}

/**
 * The newest `timestamp` across all previews, formatted the same "Aug 07, 6:15 PM" way every
 * other screen's "analyzed as of" line already does (`toAnalyzedAsOfString()`). Derived here (not
 * `last_updated` -- see `NetworkStockPreview.kt`'s doc comment on why that field is deliberately
 * unmodeled) each time `previews` changes, rather than stored redundantly per-preview.
 */
private fun List<StockPreview>.newestAnalyzedAsOf(): String? {
    val newestTimestamp = mapNotNull { it.timestamp }.maxOrNull() ?: return null
    return newestTimestamp.toAnalyzedAsOfString()
}
